      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — Create the Thank-You Page</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Create Your Form</p>
          <p class="text-slate-600 text-sm">In LeadProspectrr, create a new form with a clear name.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Add Essential Fields</p>
          <p class="text-slate-600 text-sm">Add First Name and Email as required fields.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Consider Optional Fields</p>
          <p class="text-slate-600 text-sm">Add Phone only if you truly need it for immediate follow-up.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">4</div>
        <div>
          <p class="font-semibold text-slate-900">Set Button Text</p>
          <p class="text-slate-600 text-sm">Use action-oriented button text that matches your offer.</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">5</div>
        <div>
          <p class="font-semibold text-slate-900">Configure Redirect</p>
          <p class="text-slate-600 text-sm">Set the form to redirect to your thank-you page after submission.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Create the Lead Capture Form',
      lesson_number = 4,
      sort_order = 4,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Create the Lead Capture Form';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Create the Lead Capture Form

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 8 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 8 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-lead-capture-form' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-lead-capture-form not found in module 8';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What fields should you start with for most funnels?', 
    '["Full address, company size, budget, website","First Name and Email","Social security number and birth date","Credit card information"]'::jsonb,
    'First Name and Email',
    'Start with First Name and Email. These give you what you need to follow up while keeping friction low. Add more fields only if truly necessary.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you minimize form fields?', 
    '["To make the form look prettier","More fields create more friction and reduce completion rates","Fields cost extra money","LeadProspectrr limits fields"]'::jsonb,
    'More fields create more friction and reduce completion rates',
    'Every additional field creates friction. Visitors are more likely to complete short forms. Only ask for information you truly need.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where should the form redirect after submission?', 
    '["Back to the homepage","To the thank-you page","To a competitor''s website","Nowhere, leave them on the same page"]'::jsonb,
    'To the thank-you page',
    'Always redirect to a thank-you page after form submission. This confirms the action, sets expectations, and guides them to the next step.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
